fn copy<T: Copy>(a: &Vec<T>) -> Vec<T> {
    // Pre-allocate a new Vec with the same length as `a`.
    let mut result = Vec::with_capacity(a.len());
    // Iterate over `a`, copy each element, and push it onto `result`.
    for &item in a.iter() {
        result.push(item);
    }
    result
}

fn main() {
    // Example usage
    let v = vec![1, 2, 3, 4];
    let v_copy = copy(&v);
    assert_eq!(v, v_copy);

    let chars = vec!['a', 'b', 'c'];
    let chars_copy = copy(&chars);
    assert_eq!(chars, chars_copy);
}